def calcola_stipendio(ore_lavorate, tariffa_oraria):
    # Gestione delle ore straordinarie (oltre 40 ore)
    if ore_lavorate > 40:
        ore_extra = ore_lavorate - 40
        return (40 * tariffa_oraria) + (ore_extra * tariffa_oraria * 1.5)
    return ore_lavorate * tariffa_oraria
